import React from 'react';
import { Artwork } from './db';
import './Gallery.css';

interface GalleryProps {
  artworks: Artwork[];
  onSelect: (artwork: Artwork) => void;
  onDelete: (id: string) => void;
}

const Gallery: React.FC<GalleryProps> = ({ artworks, onSelect, onDelete }) => {
  return (
    <div className="Gallery">
      {artworks.length === 0 ? (
        <div className="Empty-gallery">Your gallery is empty. Save some art!</div>
      ) : (
        <div className="Gallery-grid">
          {artworks.map((art) => (
            <div key={art.id} className="Gallery-card" onClick={() => onSelect(art)}>
              <div className="Card-image">
                <img src={art.imageData} alt={art.title} />
              </div>
              <div className="Card-info">
                <div className="Card-title">{art.title}</div>
                <div className="Card-date">{new Date(art.createdAt).toLocaleDateString()}</div>
                <button 
                  className="Delete-btn" 
                  onClick={(e) => {
                    e.stopPropagation();
                    if (art.id) onDelete(art.id);
                  }}
                >
                  &times;
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Gallery;
